bool ArchiveAllowed(quint64 owner){return !Core::App().passcodeLocked()&&(!Policy(owner,"protectArchive")||unlocked.value(owner,0)>crl::now());}
void LockArchive(){unlocked.clear();HideLockedSessions();}
